import SwiftUI
struct StageAnalysisView: View { let stages:StageBundle?; var body:some View{VStack(alignment:.leading,spacing:8){Text("9-STAGE ANALYSIS").font(.headline);s(1,"Option Direction",stages?.optionDirection?.direction,stages?.optionDirection?.confirmation);s(2,"OI / Price Action",stages?.oiPriceAction?.bias,stages?.oiPriceAction?.detail);s(3,"Support / Resistance",stages?.supportResistance?.decision,stages?.supportResistance?.detail);s(4,"Market Structure",stages?.marketStructure?.decision,stages?.marketStructure?.trend);s(5,"Order Block",stages?.orderBlock?.bias,stages?.orderBlock?.type);s(6,"Chart Pattern",stages?.chartPattern?.bias,stages?.chartPattern?.pattern);s(7,"Elliott Wave",stages?.elliottWave?.bias,stages?.elliottWave?.wave);s(8,"Confirmation Candle",stages?.confirmationCandle?.signal,stages?.confirmationCandle?.detail);s(9,"Fibonacci Retracement",stages?.fibonacci?.signal,stages?.fibonacci?.detail)}.padding().background(.thinMaterial,in:RoundedRectangle(cornerRadius:16))}
 private func s(_ n:Int,_ t:String,_ v:String?,_ d:String?)->some View{HStack(alignment:.top){Text("\(n)").bold().frame(width:25,height:25).background(Color.teal.opacity(0.12),in:Circle());VStack(alignment:.leading){HStack{Text(t).font(.subheadline.bold());Spacer();Text(v ?? "WAIT").font(.caption.bold())};if let d{Text(d).font(.caption).foregroundStyle(.secondary).lineLimit(3)}}}.padding(.vertical,3)} }

